(922872, 106078, 25017, '<td valign="top">very sweet!</td>', 'very sweet!', '2004-09-23 03:00:09.000000', NULL, 1),
(922885, 106778, 25921, '<td valign="top">I''m sure I''m not the first to say something along these lines, but I find the hand in the background distracting.  Aside from that though, this is a wonderfully tender image.  I''m not sure about the opaque border, I find it distracting as well.  Probably because the hands holding the feet are so strong emotionally and visually, the border and extra arm only take away from the impact.  Nice.</td>', 'I''m sure I''m not the first to say something along these lines, but I find the hand in the background distracting.  Aside from that though, this is a wonderfully tender image.  I''m not sure about the opaque border, I find it distracting as well.  Probably because the hands holding the feet are so strong emotionally and visually, the border and extra arm only take away from the impact.  Nice.', '2004-09-23 04:18:24.000000', NULL, 1),
(922887, 106817, 25921, '<td valign="top">I''d love to see the high res original of this.  Beautiful!</td>', 'I''d love to see the high res original of this.  Beautiful!', '2004-09-23 04:20:35.000000', NULL, 1),
(922888, 106502, 25921, '<td valign="top">What an awesome expression!  That little one is so young it wouldn''t surprise me to find that was the first smile.  Nice.</td>', 'What an awesome expression!  That little one is so young it wouldn''t surprise me to find that was the first smile.  Nice.', '2004-09-23 04:23:50.000000', NULL, 1),
