(923789, 106356, 25218, '<td valign="top">Cute! A closer crop on the people would have made it better - the couch, the window sill, and the lego thing is distracting.</td>', 'Cute! A closer crop on the people would have made it better - the couch, the window sill, and the lego thing is distracting.', '2004-09-23 18:36:22.000000', NULL, 1),
(923792, 106229, 26653, '<td valign="top">Looks like overdone curves (for my taste), and the hand just looks stuck on there, and the horse doesn''t look to happy about it.<br/>May not be the reality of it, but how it looks to me.</td>', 'Looks like overdone curves (for my taste), and the hand just looks stuck on there, and the horse doesn''t look to happy about it.May not be the reality of it, but how it looks to me.', '2004-09-23 18:37:53.000000', NULL, 1),
(923793, 106334, 26653, '<td valign="top">nice nature shot.</td>', 'nice nature shot.', '2004-09-23 18:38:08.000000', NULL, 1),
(923794, 106296, 25218, '<td valign="top">I like the tone of the picture. and it definitely is soft!</td>', 'I like the tone of the picture. and it definitely is soft!', '2004-09-23 18:38:32.000000', NULL, 1),
