(923799, 106333, 26653, '<td valign="top">very pretty flower</td>', 'very pretty flower', '2004-09-23 18:40:00.000000', NULL, 1),
(923800, 106661, 25218, '<td valign="top">Cute kid - nice shot</td>', 'Cute kid - nice shot', '2004-09-23 18:40:03.000000', NULL, 1),
