INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(924484, 106510, 26115, '<td valign="top">good idea however its a strange angle, it makes it rather hard to discern what it is that is being photo graphed so as a result possibly look at different angles but otherwise good idea</td>', 'good idea however its a strange angle, it makes it rather hard to discern what it is that is being photo graphed so as a result possibly look at different angles but otherwise good idea', '2004-09-24 07:18:33.000000', NULL, 1),
(924486, 105789, 26115, '<td valign="top">hahaha! gr8 photo, deffinitely on the lighter side ;-) <br/>*no pun intended :P* hehehe<br/>i like the colour change i really think it enhances the picture though id possibly put your subject just a tad further to the right for the added impact, the eyes are really a gr8 focal point!!!<br/>also possibly look at cropping the top of the photo so that about a third of the hair is cut out that way the reflections on the bubble wrap dont interfere and provides even more focus to the eyes!   but gr8 photo   deffinitely one that brought a laugh<br/></td>', 'hahaha! gr8 photo, deffinitely on the lighter side ;-) *no pun intended :P* hehehei like the colour change i really think it enhances the picture though id possibly put your subject just a tad further to the right for the added impact, the eyes are really a gr8 focal point!!!also possibly look at cropping the top of the photo so that about a third of the hair is cut out that way the reflections on the bubble wrap dont interfere and provides even more focus to the eyes!   but gr8 photo   deffinitely one that brought a laugh', '2004-09-24 07:22:36.000000', NULL, 1),
(924488, 105533, 20375, '<td valign="top">This is odd. This pic stopped me in my tracks. Soft focus or out of focus?<br/>Too contrasty.<br/>But....I love it. Very emotionally provocative. I feel.....empathy/sorry for him for some reason. Technically not a great picture but...it works!<br/>You;ve touched me on this one....9. I love this shot!</td>', 'This is odd. This pic stopped me in my tracks. Soft focus or out of focus?Too contrasty.But....I love it. Very emotionally provocative. I feel.....empathy/sorry for him for some reason. Technically not a great picture but...it works!You;ve touched me on this one....9. I love this shot!', '2004-09-24 07:29:40.000000', NULL, 1),
(924526, 106815, 13759, '<td valign="top">Sorry, I can´t saw the touch here, nor the touching idea.</td>', 'Sorry, I can´t saw the touch here, nor the touching idea.', '2004-09-24 08:35:47.000000', NULL, 1),
