(925788, 106094, 21083, '<td valign="top">Nice shot for this challenge.  Very touching indeed.  :)</td>', 'Nice shot for this challenge.  Very touching indeed.  :)', '2004-09-25 11:15:24.000000', NULL, 1),
(925789, 106730, 21083, '<td valign="top">Nice texture, you can almost feel this through the screen.</td>', 'Nice texture, you can almost feel this through the screen.', '2004-09-25 11:16:29.000000', NULL, 1),
(925790, 106001, 21083, '<td valign="top">Creative concept. This is a really cool shot that was well executed.</td>', 'Creative concept. This is a really cool shot that was well executed.', '2004-09-25 11:19:01.000000', NULL, 1),
(925792, 106950, 21083, '<td valign="top">This is a really creative take on the challenge. Leaving only the lower portion of the arm and hand visable against the black background is great and reduces viewer distraction from your subject. Great shot, great execution !</td>', 'This is a really creative take on the challenge. Leaving only the lower portion of the arm and hand visable against the black background is great and reduces viewer distraction from your subject. Great shot, great execution !', '2004-09-25 11:23:09.000000', NULL, 1),
