(925799, 106781, 21083, '<td valign="top">Nice concept.  Expresses touch clearly to the viewer.</td>', 'Nice concept.  Expresses touch clearly to the viewer.', '2004-09-25 11:30:51.000000', NULL, 1),
(925800, 106783, 21083, '<td valign="top">Very nicely executed shot. It does not expose the body being touched too much, but enough to allow the viewer to wonder about the sensation occuring. Excellent shot probably a winner.</td>', 'Very nicely executed shot. It does not expose the body being touched too much, but enough to allow the viewer to wonder about the sensation occuring. Excellent shot probably a winner.', '2004-09-25 11:35:41.000000', NULL, 1),
(925803, 105715, 21083, '<td valign="top">Beautifully "touching" shot.  I wish it was a little lighter though.  :)</td>', 'Beautifully "touching" shot.  I wish it was a little lighter though.  :)', '2004-09-25 11:38:02.000000', NULL, 1),
(925804, 105729, 21083, '<td valign="top">Nice shot ! Definately conveys a sense of touch to the viewer ! UGH !  :)</td>', 'Nice shot ! Definately conveys a sense of touch to the viewer ! UGH !  :)', '2004-09-25 11:38:56.000000', NULL, 1),
