(925807, 106814, 21083, '<td valign="top">You should have included "Dont Touch" on the sign, because as soon as someone sees it they automatically touch the surface !  :)  Good concept.</td>', 'You should have included "Dont Touch" on the sign, because as soon as someone sees it they automatically touch the surface !  :)  Good concept.', '2004-09-25 11:46:29.000000', NULL, 1),
(925808, 106170, 21606, '<td valign="top">This is my favorite photo in this challenge. It is almost saying either two things. "Hey, Get out of my way." or "Peace". This is wonderful, and a good macro. 10</td>', 'This is my favorite photo in this challenge. It is almost saying either two things. "Hey, Get out of my way." or "Peace". This is wonderful, and a good macro. 10', '2004-09-25 11:46:56.000000', NULL, 1),
