(926691, 106956, 26518, '<td valign="top">Got a bright reflection on the top hand.  Otherwise a great photo with emotional impact.</td>', 'Got a bright reflection on the top hand.  Otherwise a great photo with emotional impact.', '2004-09-26 14:19:03.000000', NULL, 1),
