(926693, 106960, 10818, '<td valign="top">Probably the best idea of the contest....very well done.</td>', 'Probably the best idea of the contest....very well done.', '2004-09-26 14:22:00.000000', NULL, 1),
(926702, 106144, 21714, '<td valign="top">I really like this one. Love the colours and contrast. I somehow do feel uncomfortable with how it''s cropped from her neck Makes me wonder if this shot would have worked better with may be a wee bit of her chin. Because of the positioning of her shoulders, it does create the look of a chicken from the frozen counter. That''s what I am uncomfortable with. But as I said before, I think it''s a great shot.</td>', 'I really like this one. Love the colours and contrast. I somehow do feel uncomfortable with how it''s cropped from her neck Makes me wonder if this shot would have worked better with may be a wee bit of her chin. Because of the positioning of her shoulders, it does create the look of a chicken from the frozen counter. That''s what I am uncomfortable with. But as I said before, I think it''s a great shot.', '2004-09-26 14:38:32.000000', NULL, 1),
(926706, 106329, 21714, '<td valign="top">Cool idea &amp; very good control of lighting. Love the composition. Well done.</td>', 'Cool idea & very good control of lighting. Love the composition. Well done.', '2004-09-26 14:40:03.000000', NULL, 1),
(926709, 106940, 21714, '<td valign="top">Very cool composition and love the tonality of the image. Well done.</td>', 'Very cool composition and love the tonality of the image. Well done.', '2004-09-26 14:41:15.000000', NULL, 1),
(926715, 106729, 21714, '<td valign="top">Beautiful image. Brilliant capture - Excellent composition. I can even smell the baby smell! Well done!</td>', 'Beautiful image. Brilliant capture - Excellent composition. I can even smell the baby smell! Well done!', '2004-09-26 14:44:04.000000', NULL, 1),
(926737, 106844, 10818, '<td valign="top">What a cute photo.  Cute kids and nice shot for this contest..  Personally I dont care for the frame....but very nice.</td>', 'What a cute photo.  Cute kids and nice shot for this contest..  Personally I dont care for the frame....but very nice.', '2004-09-26 15:14:08.000000', NULL, 1),
