INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(926790, 105918, 10818, '<td valign="top">Fantastic horse photo,...well done.</td>', 'Fantastic horse photo,...well done.', '2004-09-26 16:33:20.000000', NULL, 1),
(926807, 105929, 21521, '<td valign="top">Very nice saturation!</td>', 'Very nice saturation!', '2004-09-26 17:04:38.000000', NULL, 1),
(926811, 106502, 10818, '<td valign="top">Oh my that smile is just priceless.....beautifil photo !</td>', 'Oh my that smile is just priceless.....beautifil photo !', '2004-09-26 17:15:49.000000', NULL, 1),
(926813, 106859, 10818, '<td valign="top">Great clown fish photo, he has great colors...wonderful anemones....orignal and appropriate for the contest.</td>', 'Great clown fish photo, he has great colors...wonderful anemones....orignal and appropriate for the contest.', '2004-09-26 17:22:17.000000', NULL, 1),
(926814, 106502, 6804, '<td valign="top">This, to me, is what photography is all about.  Pictures of children will rate well, even on DPC, if you can present them in a way that pulls emotion from the viewer.  This is my favorite of the challenge and I hope to see it in Parenting Magazine or any number of other places that I''m sure would love to be able publish this.  The pose and expression of the child are exceptional.  Congratulations on an award winning shot ! ! !       Certainly a 10 from me.</td>', 'This, to me, is what photography is all about.  Pictures of children will rate well, even on DPC, if you can present them in a way that pulls emotion from the viewer.  This is my favorite of the challenge and I hope to see it in Parenting Magazine or any number of other places that I''m sure would love to be able publish this.  The pose and expression of the child are exceptional.  Congratulations on an award winning shot ! ! !       Certainly a 10 from me.', '2004-09-26 17:24:04.000000', NULL, 1),
(926815, 106598, 6804, '<td valign="top">This is a truly stunning capture.</td>', 'This is a truly stunning capture.', '2004-09-26 17:27:47.000000', NULL, 1),
(926816, 105607, 17442, '<td valign="top">not sure how this relates to the challange</td>', 'not sure how this relates to the challange', '2004-09-26 17:30:13.000000', NULL, 1),
(926818, 106714, 17442, '<td valign="top">interesting idea, to much red saturation</td>', 'interesting idea, to much red saturation', '2004-09-26 17:31:51.000000', NULL, 1),
(926832, 106752, 17442, '<td valign="top">love the image, just not for this challenge. nice depth of field, great color scale, good imagery</td>', 'love the image, just not for this challenge. nice depth of field, great color scale, good imagery', '2004-09-26 17:40:42.000000', NULL, 1),
(926845, 106598, 17442, '<td valign="top">landscape, weather, still life -- i can see.  but touch?</td>', 'landscape, weather, still life -- i can see.  but touch?', '2004-09-26 17:45:23.000000', NULL, 1),
(926875, 106499, 23338, '<td valign="top">I don''t see the tie between "have a peanut" and "touch".   However, it IS a nice image - good contrast against the black background, nice color and composition.  The subject matter (peanut shell) tends to photograph slightly soft (not much to focus on other than outline).  Good luck with the challenge.</td>', 'I don''t see the tie between "have a peanut" and "touch".   However, it IS a nice image - good contrast against the black background, nice color and composition.  The subject matter (peanut shell) tends to photograph slightly soft (not much to focus on other than outline).  Good luck with the challenge.', '2004-09-26 18:12:13.000000', NULL, 1),
(926879, 105774, 23338, '<td valign="top">"The touch"?  Ok, let me guess - you''re an artist and you have that "touch" required for decorating an apartment or home?  Problem for me is that I wouldn''t have come up with that without the title ...  and maybe I still haven''t gotten your message correct even with that guess.  I''ve been looking for more literal interpretations of touch in this challenge.   Sorry.  Good luck with the challenge.</td>', '"The touch"?  Ok, let me guess - you''re an artist and you have that "touch" required for decorating an apartment or home?  Problem for me is that I wouldn''t have come up with that without the title ...  and maybe I still haven''t gotten your message correct even with that guess.  I''ve been looking for more literal interpretations of touch in this challenge.   Sorry.  Good luck with the challenge.', '2004-09-26 18:16:01.000000', NULL, 1),
(926905, 105944, 24841, '<td valign="top">Perfect lips.  Cropped perfectly.</td>', 'Perfect lips.  Cropped perfectly.', '2004-09-26 19:32:20.000000', NULL, 1),
(926906, 106773, 22856, '<td valign="top">The b/w effect works verry good, nice picture, good quality!</td>', 'The b/w effect works verry good, nice picture, good quality!', '2004-09-26 19:33:00.000000', NULL, 1),
(926908, 105561, 27216, '<td valign="top">I definitely want to touch this cute puppy - nice capture</td>', 'I definitely want to touch this cute puppy - nice capture', '2004-09-26 19:33:55.000000', NULL, 1),
(926909, 105489, 24841, '<td valign="top">I tried for this same shot and couldn''t accomplish it, GREAT job! 8</td>', 'I tried for this same shot and couldn''t accomplish it, GREAT job! 8', '2004-09-26 19:34:08.000000', NULL, 1),
(926911, 106969, 27216, '<td valign="top">Way too gross for my taste</td>', 'Way too gross for my taste', '2004-09-26 19:34:34.000000', NULL, 1),
(926943, 106843, 25655, '<td valign="top">Makes me feel cold... It looks more like ice then hot water...<br/>Yet, a wonderful capture and definately makes me feel you !</td>', 'Makes me feel cold... It looks more like ice then hot water...Yet, a wonderful capture and definately makes me feel you !', '2004-09-26 20:08:39.000000', NULL, 1),
(926980, 106144, 19953, '<td valign="top">I think the right side of the shot needs more light.  The harsh lighting to the left lowers my mood when I look at the shot &amp; I generally think of impending motherhood as a mood lifter...Just my opinion...</td>', 'I think the right side of the shot needs more light.  The harsh lighting to the left lowers my mood when I look at the shot & I generally think of impending motherhood as a mood lifter...Just my opinion...', '2004-09-26 20:37:10.000000', NULL, 1),
(926986, 106921, 23338, '<td valign="top">Great portrait.  You can almost FEEL those little foot pads clinging...  :-)   And another great frog image goes into the record books.  Congratulations and good luck with the challenge.</td>', 'Great portrait.  You can almost FEEL those little foot pads clinging...  :-)   And another great frog image goes into the record books.  Congratulations and good luck with the challenge.', '2004-09-26 20:47:01.000000', NULL, 1),
(927009, 106712, 19608, '<td valign="top">This image is a real problem for me. There are many areas where the exposure is way over, no detail at all in the white.  In most situations, I would not like that effect.  BUt I LOVE it in this image, because the white areas are framing that wonderful center of the blossom.  Thne there''s your depth of field.  The center (of the flower) is so very crisp - and there''s plenty of detail in the underlying green leaves.  The small spots on the white petals are a bit unfortunate, but with basic editing - not much you could do.  Overall - a top entry - thanks for sharing.</td>', 'This image is a real problem for me. There are many areas where the exposure is way over, no detail at all in the white.  In most situations, I would not like that effect.  BUt I LOVE it in this image, because the white areas are framing that wonderful center of the blossom.  Thne there''s your depth of field.  The center (of the flower) is so very crisp - and there''s plenty of detail in the underlying green leaves.  The small spots on the white petals are a bit unfortunate, but with basic editing - not much you could do.  Overall - a top entry - thanks for sharing.', '2004-09-26 21:29:30.000000', NULL, 1),
(927012, 106598, 19608, '<td valign="top">You have a very graphic scene - and yes it does make one feel the mist.  It''s not the strongest suggestion of touch, but there nonetheless.  The leading lines from the bottom right into the image are excellent.</td>', 'You have a very graphic scene - and yes it does make one feel the mist.  It''s not the strongest suggestion of touch, but there nonetheless.  The leading lines from the bottom right into the image are excellent.', '2004-09-26 21:31:38.000000', NULL, 1),
(927027, 106829, 19608, '<td valign="top">I want to play too!  Great image for touch - well thought out, composed and exposed.  Great textures abound.</td>', 'I want to play too!  Great image for touch - well thought out, composed and exposed.  Great textures abound.', '2004-09-26 21:51:27.000000', NULL, 1),
(927029, 106729, 19608, '<td valign="top">Excellent feeling of touch - but a wee bit soft.  Composition is great as is exposure.</td>', 'Excellent feeling of touch - but a wee bit soft.  Composition is great as is exposure.', '2004-09-26 21:53:11.000000', NULL, 1),
(927035, 106520, 19608, '<td valign="top">Makes my skin itch just looking at it - wait... that''s what it''s supposed to do!  Nice take on the challenge.</td>', 'Makes my skin itch just looking at it - wait... that''s what it''s supposed to do!  Nice take on the challenge.', '2004-09-26 22:01:16.000000', NULL, 1),
(927037, 106650, 19608, '<td valign="top">A very special image.  The slow exposure and the noise both work to enhance the feel.  I like his face a lot with the yes closed - that also adds to the magic of the image</td>', 'A very special image.  The slow exposure and the noise both work to enhance the feel.  I like his face a lot with the yes closed - that also adds to the magic of the image', '2004-09-26 22:05:07.000000', NULL, 1),
(927039, 106007, 19608, '<td valign="top">Sticky!  Nice composition and idea.  Exposure is right on as is the diagonal composition.  The border works ok - but is a bit heavy.</td>', 'Sticky!  Nice composition and idea.  Exposure is right on as is the diagonal composition.  The border works ok - but is a bit heavy.', '2004-09-26 22:07:31.000000', NULL, 1),
(927040, 106754, 19608, '<td valign="top">A special moment well captured.  VEry "touching" indeed.</td>', 'A special moment well captured.  VEry "touching" indeed.', '2004-09-26 22:10:41.000000', NULL, 1),
(927042, 106609, 19608, '<td valign="top">Eww.  Not fun.</td>', 'Eww.  Not fun.', '2004-09-26 22:13:31.000000', NULL, 1),
(927044, 105822, 19608, '<td valign="top">It''s a very graphic and pleasing image.  The light pattern on the ceiling is really magic.  I am struggling a bit with touch, but assumig you had a connection...</td>', 'It''s a very graphic and pleasing image.  The light pattern on the ceiling is really magic.  I am struggling a bit with touch, but assumig you had a connection...', '2004-09-26 22:17:06.000000', NULL, 1),
(927047, 106814, 26464, '<td valign="top">nice texture!</td>', 'nice texture!', '2004-09-26 22:18:00.000000', NULL, 1),
(927048, 106499, 19608, '<td valign="top">Oh no you don''t!  I''m not touching that!  Then there will #2, #3, #99.....<br/>Excellent macro.</td>', 'Oh no you don''t!  I''m not touching that!  Then there will #2, #3, #99.....Excellent macro.', '2004-09-26 22:19:21.000000', NULL, 1),
