INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1439266, 105918, 3214, '<td valign="top">Am staggered by the amount of 4s and below on this image.  The foal is touching her mama along her entire side, and of course nursing is nothing but touch.  And it''s sharp with decent lighting, composition and toning.  Maybe people think how tight the crop is doesn''t work--but of course only one comment to indicate...</td>', 'Am staggered by the amount of 4s and below on this image.  The foal is touching her mama along her entire side, and of course nursing is nothing but touch.  And it''s sharp with decent lighting, composition and toning.  Maybe people think how tight the crop is doesn''t work--but of course only one comment to indicate...', '2005-06-07 18:56:54.000000', NULL, 0),
(1455429, 106298, 38223, '<td valign="top">ehm? I have tried melting marshmallows in the microwave for weird artistic purposes, and that stuff is really nasty and hard to remove after it has cooled down (and it cools down pretty fast)<br/> <br/>Had any troubles with removing it from the face? Good thing you didn''t get that in your facial hair :)</td>', 'ehm? I have tried melting marshmallows in the microwave for weird artistic purposes, and that stuff is really nasty and hard to remove after it has cooled down (and it cools down pretty fast) Had any troubles with removing it from the face? Good thing you didn''t get that in your facial hair :)', '2005-06-14 18:11:39.000000', NULL, 0),
(1455702, 106780, 368, '<td valign="top">i do like this image .. the contrast of iamges in the shot are definitly portraying a message ... with the challenge being touch though - i''m still not sure i see the connection ... but the detail of the stuffed animal is beasutiful and i do think the b/w works well here.</td>', 'i do like this image .. the contrast of iamges in the shot are definitly portraying a message ... with the challenge being touch though - i''m still not sure i see the connection ... but the detail of the stuffed animal is beasutiful and i do think the b/w works well here.', '2005-06-14 20:21:48.000000', NULL, 0),
(1628741, 106016, 16739, '<td valign="top">you have talent ! keep it up.</td>', 'you have talent ! keep it up.', '2005-08-21 20:17:18.000000', NULL, 0),
