(1841803, 105604, 47274, '<td valign="top">wow</td>', 'wow', '2005-11-06 07:21:54.000000', NULL, 0),
(2272902, 106963, 26845, '<td valign="top">10 1''s, 21 2''s, 38 3''s? I guess people are not open minded enough to understand the idea of implication, implied touch, or desire to touch something or want to because of a texture you see or feel in your mind but not in your head.</td>', '10 1''s, 21 2''s, 38 3''s? I guess people are not open minded enough to understand the idea of implication, implied touch, or desire to touch something or want to because of a texture you see or feel in your mind but not in your head.', '2006-03-30 09:26:18.000000', NULL, 0),
