(2472516, 105694, 52439, '<td valign="top">Really nice shot.<br/>The negative space really concentrates you on the focus of the hand.<br/>Great idea to desaturate aswell, looks silver and more interesting.<br/></td>', 'Really nice shot.The negative space really concentrates you on the focus of the hand.Great idea to desaturate aswell, looks silver and more interesting.', '2006-05-31 15:48:13.000000', NULL, 0),
(2542938, 105694, 37893, '<td valign="top">This is a good shot but would have preferred it to be in one of the thirds so that the negative space around the hand would really show. Still a good image :)</td>', 'This is a good shot but would have preferred it to be in one of the thirds so that the negative space around the hand would really show. Still a good image :)', '2006-06-22 22:42:33.000000', NULL, 0),
(2592111, 106502, 55838, '<td valign="top">WOW.  First time to your profile as I am fairly new to DPC.  I LOVE this pic.  Absolutely perfect and absolutely communicates security.  Adding to favorites.</td>', 'WOW.  First time to your profile as I am fairly new to DPC.  I LOVE this pic.  Absolutely perfect and absolutely communicates security.  Adding to favorites.', '2006-07-06 06:40:20.000000', NULL, 0),
(2622729, 106699, 55738, '<td valign="top">I''m not in love with the grain, but I do love that some of it is a bit overexposed. I''d like to see you push that even farther.  But then, I''m someone who likes pretty high contrasty things.  Great idea here!</td>', 'I''m not in love with the grain, but I do love that some of it is a bit overexposed. I''d like to see you push that even farther.  But then, I''m someone who likes pretty high contrasty things.  Great idea here!', '2006-07-14 16:04:43.000000', NULL, 0),
